T(27, "27-5", "The Discovery of Penicillin", "Recount (Historical)", [
"In the summer of 1928, a Scottish scientist named Alexander Fleming packed a bag and went on holiday. He worked in a laboratory at St Mary\u2019s Hospital in London, where he was studying germs called bacteria. Before he left, he had spread bacteria onto several small glass dishes so they could grow, and he left the dishes stacked on his workbench.",
"When Fleming came back in September, he began to sort through the dishes. Most of them looked as he expected, but one caught his eye. A fuzzy patch of blue-green mould had grown on it. Moulds are common, and a scientist might easily have thrown the dish away. Fleming, however, looked closer and noticed something odd. All around the mould, the bacteria had disappeared. The dish was clear in a small ring, while the rest of it was cloudy with bacteria.",
"\u201cThat\u2019s funny,\u201d he is said to have murmured. He guessed that the mould must be making a substance that killed the bacteria. He carefully grew more of the mould, which turned out to be a kind called Penicillium, and found that a liquid taken from it could stop many harmful bacteria from growing. He named the liquid penicillin.",
"Fleming knew that his discovery might be important, because bacteria cause many illnesses, some of which doctors could do little to treat at that time. He was careful, too, to test his liquid on many different kinds of bacteria, so that he could tell which ones it stopped. In 1929, he wrote about it in a science journal. Still, making penicillin was difficult. Fleming could grow only a tiny amount of the liquid, and it was not pure enough to be used as medicine. He tried to interest other scientists, but for years little happened.",
"In the late 1930s, a group of scientists at Oxford University, led by Howard Florey and Ernst Chain, read Fleming\u2019s work with interest. They decided to try to make penicillin in larger amounts. It took long hours in the laboratory, and they had to work out how to purify the liquid so it would be safe. Slowly, they succeeded.",
"By the 1940s, factories were producing penicillin, and doctors began to use it to treat people with serious infections. It was the first of a group of medicines called antibiotics. In 1945, Fleming, Florey and Chain shared a famous prize for their work.",
"Alexander Fleming\u2019s story shows how important it is to notice small things. A dish that others might have thrown away led to a medicine that has helped millions of people. Fleming had the patience to look twice, and the Oxford team had the determination to turn a curious mould into a cure.",
], [
 dict(d="2b",k="mc",m=1,q="Where did Alexander Fleming work?",opts=["A school in Scotland","A laboratory at St Mary\u2019s Hospital in London","A factory in Oxford","A farm in the countryside"],a="B"),
 dict(d="2b",k="find",m=1,q="Find and copy the two words in paragraph 2 that describe the colour of the mould.",a="blue-green",g="Accept \u201cblue-green\u201d."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does the word \u201cpurify\u201d mean?",opts=["Make it stronger","Make it clean by removing other things","Make it colder","Make it cheaper"],a="B"),
 dict(d="2d",k="short",m=1,q="Why might a scientist \u201ceasily have thrown the dish away\u201d?",a="Because moulds are common and it looked like an ordinary, spoilt dish.",g="Accept: mould is common / it looked spoilt."),
 dict(d="2d",k="short",m=1,q="What did Fleming notice that made him look closer at the dish?",a="The bacteria had disappeared in a ring around the mould.",g="Accept: a clear ring around the mould."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order they happened.",items=["Fleming named the liquid penicillin.","Fleming came back from holiday.","Factories began producing penicillin.","Fleming saw a ring around the mould."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["The discovery was made in 1928.","Fleming could make lots of pure penicillin himself.","Florey and Chain worked at Oxford University.","Penicillin was the first antibiotic."],a=["T","F","T","T"],g=TF),
 dict(d="2d",k="short",m=1,q="Why did little happen for years after Fleming wrote about his discovery?",a="Penicillin was hard to make, he could only grow a small amount, and it was not pure enough for medicine.",g="Accept any one of these reasons."),
 dict(d="2d",k="short",m=1,q="Why was the work of the Oxford scientists needed after Fleming\u2019s discovery?",a="They found a way to make penicillin in larger amounts and pure enough to be used as medicine.",g="Accept: to make more of it / to purify it."),
 dict(d="2g",k="short",m=1,q="The writer says Fleming \u201cis said to have murmured\u201d, \u201cThat\u2019s funny.\u201d What does the phrase \u201cis said to have\u201d tell the reader?",a="That people say he said it, but we cannot be sure.",g="Accept: it may not be exactly what he said / not certain."),
 dict(d="2c",k="mc",m=1,q="Which of these is the best summary of paragraph 5?",opts=["Oxford scientists worked to make penicillin in larger amounts.","Fleming retired from his work.","Doctors stopped using penicillin.","A factory closed down."],a="A"),
 dict(d="2d",k="short",m=2,q="Give two reasons why Fleming\u2019s discovery mattered.",a="Bacteria cause many illnesses; penicillin could treat serious infections; it has helped millions of people; it began the antibiotics.",g="1 mark for each. Max 2."),
 dict(d="2c",k="mc",m=1,q="What is the main lesson of the last paragraph?",opts=["Noticing small things can lead to great discoveries.","Scientists should go on holiday more often.","Mould is always dangerous.","Bacteria are easy to grow."],a="A"),
 dict(d="2e",k="short",m=1,q="What might have happened if Fleming had thrown the dish away without looking closely? Use the text to help you.",a="The discovery of penicillin might have been delayed or missed.",g="Accept any answer linking to the discovery not being made."),
])

T(27, "27-6", "The Arctic Tern: Champion Traveller", "Information Report", [
"The Arctic tern is a slim seabird, weighing about as much as a bar of chocolate. It has a black cap, a bright red beak, and long, forked tail feathers that flutter like ribbons. Yet this small bird makes the longest journey of any animal on Earth.",
"In the northern summer, Arctic terns nest in the far north, in places such as Greenland, Iceland and northern Britain. When the northern autumn approaches, the days shorten and the fish become harder to find. The terns then fly all the way south to the seas around Antarctica, which are just entering their summer. In the spring, they fly back again. Some birds travel more than seventy thousand kilometres in a single year, which is well over one and a half times the distance around the Earth.",
"Because they move from one summer to the next, Arctic terns see more daylight than any other creature. They do not fly in a straight line. Instead, they take a winding path that lets them use the winds to help them, and they save energy by gliding. Birds tracked with tiny devices strapped to their legs have shown that they often zigzag across the ocean instead of flying in a straight line.",
"The terns are excellent fishers. They hover above the water, watching for small fish, and then plunge headfirst to grab them. Before they set off on their journey south, they must eat plenty of fish to store energy. During the journey, they rest on the sea or catch food while flying.",
"The terns are noisy and defiant nesters. They make shallow scrapes on open ground, usually on beaches or on rocky islands. Each pair lays one to three eggs, and both parents take turns keeping them warm. If any intruder wanders near, the terns will swoop down and peck it on the head. This behaviour is very effective at protecting the chicks, and even large animals and human visitors are wise to wear hats.",
"Young terns learn to fly about three weeks after hatching. Until then, the parents bring them small fish, carrying each one carefully in the beak and dropping it beside the chick. They then follow their parents south on their first big journey. An Arctic tern can live for about thirty years, and over its lifetime, it may fly a distance equal to several trips to the Moon and back.",
"Scientists are keen to keep learning about these travellers. Small tracking devices are now so light that a bird can carry one without noticing. This is important, because changes in the sea and in the weather may affect where fish are found. If the fish move, the terns will need to find them. Protecting nesting places and keeping the oceans healthy will help these remarkable birds to keep making their long journeys for many years to come.",
], [
 dict(d="2b",k="mc",m=1,q="What colour is the Arctic tern\u2019s beak?",opts=["Yellow","Black","Orange","Bright red"],a="D"),
 dict(d="2b",k="short",m=1,q="Where do Arctic terns spend the northern winter?",a="In the seas around Antarctica.",g="Accept: Antarctica / the far south."),
 dict(d="2a",k="mc",m=1,q="In paragraph 5, what does the word \u201cdefiant\u201d mean?",opts=["Boldly standing up to threats","Very shy","Rather sleepy","Easy to please"],a="A"),
 dict(d="2b",k="find",m=1,q="Find and copy the words that tell you how the terns catch fish after hovering.",a="plunge headfirst",g="Accept \u201cplunge headfirst\u201d."),
 dict(d="2d",k="short",m=1,q="Why do Arctic terns see more daylight than any other creature?",a="They move from one summer to the other, so they are in the daylight of both summers.",g="Accept: they live in two summers in a year."),
 dict(d="2d",k="short",m=1,q="Why do the terns fly south when autumn approaches?",a="The days shorten and fish become harder to find.",g="Accept either."),
 dict(d="2c",k="order",m=1,q="Number the events from 1 to 4 to show the order in an Arctic tern\u2019s year.",items=["The tern flies to Antarctica.","The tern flies back north.","The tern nests in the far north.","The tern eats plenty of fish."],a=[3,1,4,2],g=Q2),
 dict(d="2b",k="tf",m=1,q="Tick True or False for each sentence.",items=["Arctic terns are heavy birds.","Some terns fly more than seventy thousand kilometres a year.","Terns nest in trees.","Both parents keep the eggs warm."],a=["F","T","F","T"],g=TF),
 dict(d="2d",k="short",m=1,q="Why does the writer say that \u201chuman visitors are wise to wear hats\u201d?",a="Because the terns swoop and peck intruders on the head.",g="Accept: to protect their heads."),
 dict(d="2g",k="short",m=1,q="The writer says the tail feathers \u201cflutter like ribbons\u201d. What does this comparison suggest?",a="That the tail feathers are long, light and move gracefully.",g="Accept: long, thin, light or delicate."),
 dict(d="2d",k="short",m=2,q="Give two ways that Arctic terns protect their chicks or prepare for flights.",a="They swoop and peck intruders; both parents keep eggs warm; they eat plenty of fish before the journey.",g="1 mark for each way. Max 2."),
 dict(d="2c",k="mc",m=1,q="Which of these is the best heading for paragraph 3?",opts=["The ways terns choose their route","How terns make nests","Why terns are afraid of ships","Foods that terns like"],a="A"),
 dict(d="2c",k="mc",m=1,q="What is the main idea of the whole text?",opts=["The Arctic tern is a small bird that makes an incredible journey each year.","Terns are the biggest seabirds.","Terns never rest.","Fish are harder to find in the north."],a="A"),
 dict(d="2e",k="short",m=1,q="What might happen to the terns if the fish moved to different places? Use the last paragraph to help you.",a="They would need to find the fish in the new places, changing where they go.",g="Accept: they would have to travel further or change route to follow the fish."),
])
